    'Page {page} of {pages}' => 'Seite {page} von {pages}',
    'No events here. They appear after the first sync of a calendar.' => 'Hier sind keine Termine. Sie erscheinen nach dem ersten Abgleich eines Kalenders.',
    'All runs' => 'Alle Läufe',
    'Only runs with errors' => 'Nur Läufe mit Fehlern',
    'Only runs without errors' => 'Nur Läufe ohne Fehler',
